out={'phase':'3W','application_change':'NONE','base':comparison['base'],'harness_commit':comparison['harness_commit'],'harness_tree':comparison['harness_tree'],'intended_harness_head':comparison['intended_harness_head'],'http_requests':total,'http_errors':errors,'sql_errors':sqlerrors,'missing_metrics':missing,'cap_refused':refused,'response_comparisons':comparison['response_comparisons'],'serial':[{'schema':k[0],'index':k[1],'phase':k[2],'operation':k[3],'p50_ms_median':statistics.median(v),'per_pool_p50_ms':v}for k,v in serial.items()],'native':[{'schema':k[0],'index':k[1],'dataset':k[2],'phase':k[3],'median_ms':statistics.median(v),'per_pool_medians_ms':v}for k,v in native.items()],'load':loads,'runs':runs,'ci':{'status':'PENDING pre-CI publication snapshot; exact-head verification in final PR body/handoff.'},'limitations':['All pools OPcache on; no new on/off comparison.','Minimal write-ready fixture has explicit missing-column/default corrections.','Full-derived schema seeded with controlled core rows; ancillary contents differ from minimal.','Index states compared within each flavour, not claimed cross-flavour API parity or production parity.','Mixed mutable read snapshots retained but not equated across independent interleavings.','Natural lock sampling can miss short waits; induced control is separate.','SQL counts are application PDO operations, not server-internal statement or database CPU totals.','Non-scalar/non-UTF8 bound values explicitly unreplayable; no guessed inputs.','Process telemetry unavailable remains BLOCKED.','Thirty-second loopback synthetic cells do not certify50–100 students or target VPS capacity.']}
